/**  Every mode removes this PC's token file and key lines. */
export type CleanupMode = 
/**  Also removes the helper when no PC holds a token any more, as a cancelled pairing does. */
"unused" | 
/**  Also removes the helper, which disconnects every other PC. */
"uninstall";

export type CleanupOutcome = { status: "done" } | 
/**  The headset rejects this PC's key, so the cleanup changed nothing on it. */
{ status: "rejected" } | { status: "unreachable" } | { status: "hostKeyChanged" } | { status: "failed"; message: string };

export type CleanupRequest = CleanupRequest_Serialize | CleanupRequest_Deserialize;

export type CleanupRequest_Deserialize = {
	access: Access_Deserialize,
	pcId: string,
	publicKey: string,
	mode: CleanupMode,
};

export type CleanupRequest_Serialize = {
	access: Access_Serialize,
	pcId: string,
	publicKey: string,
	mode: CleanupMode,
};

export type Control = "brightness" | "cct";

export type Controller = {
	serial: string,
	connected: boolean,
};

export type DebugSnapshot = {
	quaternion: [number, number, number, number],
	geometry: PoseGeometry,
	rawPose: SleepingPose,
	stablePose: SleepingPose,
};

export type DisableResult = { result: "ok" } | { result: "cleanupFailed"; reason: string };

export type DisconnectControllerError = "runtimeUnavailable" | "writeFailed" | 
/**  No open connection, or it closed before the helper replied. */
"offline";

export type EnableResult = { result: "ok" } | 
/**  The user dismissed the UAC prompt. */
{ result: "promptDeclined" } | { result: "installFailed" } | { result: "taskFailed"; reason: string; 
/**  A fixed identifier for telemetry. Never a path, SID, or other text about the machine. */
code: string } | 
/**  Not an administrator account, so these features stay unavailable. */
{ result: "notSupported" };

export type FadeError = "unsupported" | "runtimeUnavailable" | "writeFailed" | 
/**  No open connection, or it closed before the helper replied. */
"offline";

